/** Engine font image, 8x8 font provided by the engine
 *  @type {ImageFont}
 *  @memberof Draw */
let engineImageFont;

/**
 * Image Font Object - Draw text by using tiles in an image
 * - 96 characters (from space to tilde) are stored in an image
 * - A 8x8 default engine font is supplied for general use
 * - This system is WebGL enabled for fast text rendering
 * - Fonts can also be colored and scaled along each axis
 *
 * @memberof Draw
 * @example
 * // use built in font
 * const font = engineImageFont;
 *
 * // draw text
 * font.drawTextScreen('LittleJS\nHello World!', vec2(200, 50), 16);
 */
class ImageFont
{
    /** Create an image font
     *  @param {TileInfo} tileInfo - Tile info of first character in font
     */
    constructor(tileInfo)
    {
        ASSERT(!!tileInfo, 'tileInfo is required for ImageFont');
        
        /** @property {TileInfo} - Tile info for the font */
        this.tileInfo = tileInfo; // kept, not copied, so a loadSprite tile filled in once it loads is seen
    }

    /** Draw text in world space using the image font
     *  - The text stays upright and ignores cameraAngle, each glyph is snapped to whole screen pixels to keep it crisp
     *  @param {string|number} text
     *  @param {Vector2} pos
     *  @param {Vector2|number} [size]
     *  @param {boolean} [center=true] - center each line on pos, and the lines of multi-line text around it
     *  @param {Color} [color=WHITE]
     *  @param {boolean} [useWebGL=glEnable]
     *  @param {CanvasRenderingContext2D|OffscreenCanvasRenderingContext2D} [context] 
     */
    drawText(text, pos, size=1, center, color, useWebGL, context)
    {
        ASSERT(isVector2(size) || typeof size === 'number', 'size must be a vec2 or number');

        if (typeof size === 'number')
        {
            // if size is a number, make it a vector
            ASSERT(size > 0);
            size *= cameraScale;
            size = new Vector2(size, size);
        }
        else
            size = size.scale(cameraScale);
        // world text, only drawn through screen space, so it still casts in a pass that skips screen space draws
        const skip = glSkipScreenSpace;
        glSkipScreenSpace = false;
        this.drawTextScreen(text, worldToScreen(pos), size, center, color, useWebGL, context);
        glSkipScreenSpace = skip;
    }

    /** Draw text in screen space using the image font
     *  @param {string|number} text
     *  @param {Vector2} pos
     *  @param {Vector2|number} size
     *  @param {boolean} [center] - center each line on pos, and the lines of multi-line text around it
     *  @param {Color} [color=WHITE]
     *  @param {boolean} [useWebGL=glEnable]
     *  @param {CanvasRenderingContext2D|OffscreenCanvasRenderingContext2D} [context]
     */
    drawTextScreen(text, pos, size, center=true, color=WHITE, useWebGL=glEnable, context)
    {
        ASSERT(isStringLike(text), 'text must be a string');
        ASSERT(isVector2(pos), 'pos must be a vec2');
        ASSERT(isVector2(size) || typeof size === 'number', 'size must be a vec2 or number');
        ASSERT(typeof center === 'boolean', 'center must be a boolean, the color comes after it, unlike drawText');
        ASSERT(isColor(color), 'color must be a color');

        // if size is a number, make it a vector
        const glyphSize = typeof size === 'number' ? new Vector2(size, size) : size;

        // precache objects for drawing, a copy of the tile info each glyph moves, the font's own stays put
        const drawPos = new Vector2;
        const tileInfo = this.tileInfo.frame(0);

        // draw each line of text, centered vertically like drawTextScreen when center is set
        const lines = (text+'').split('\n');
        const centerOffsetY = center ? (lines.length-1) * glyphSize.y / 2 : 0;
        lines.forEach((line, j)=>
        {
            const centerOffset = center ? (line.length-1) * glyphSize.x / 2 : 0;
            for (let i=line.length; i--;)
            {
                // get the glyph, out of range characters use the last one
                const charCode = line.charCodeAt(i);
                this.getGlyphPos(charCode < 32 || charCode > 127 ? 95 : charCode - 32, tileInfo.pos);

                // snap the glyph edges to whole pixels
                // tiles are drawn from their center, so snapping the center
                // to a whole pixel puts the edges on half pixels when the
                // size is even, and a row or column of the glyph then has
                // no pixel center inside it and is not rasterized at all
                // ceil picks the nearest aligned position, breaking ties
                // downward to match how this used to truncate
                drawPos.x = ceil(pos.x + i * glyphSize.x - centerOffset - glyphSize.x/2) + glyphSize.x/2 - .5;
                drawPos.y = ceil(pos.y + j * glyphSize.y - centerOffsetY - glyphSize.y/2) + glyphSize.y/2 - .5;
                drawTile(drawPos, glyphSize, tileInfo, color, 0, false, undefined, useWebGL, true, context);
            }
        });
    }

    /** Get where a glyph sits in the texture: counted in the font's own columns when its tile has them, like a font
     *  packed by loadSprite, otherwise along the texture's grid from the font's first tile, the way tile() lays it out
     *  @param {number} index - Glyph number, 0 is the space and the characters follow in ASCII order
     *  @param {Vector2} [pos] - Written into and returned, for a loop that places many
     *  @return {Vector2} */
    getGlyphPos(index, pos=new Vector2)
    {
        const t = this.tileInfo, padding = t.padding;
        const w = t.size.x + padding*2, h = t.size.y + padding*2;
        if (t.columns)
            return pos.set(t.pos.x + index % t.columns * w, t.pos.y + (index / t.columns |0) * h);
        const columns = t.textureInfo.size.x / w |0;
        const glyph = ((t.pos.y - padding) / h |0) * columns + ((t.pos.x - padding) / w |0) + index;
        return pos.set(glyph % columns * w + padding, (glyph / columns |0) * h + padding);
    }
}

// how strong a light's glow is at a distance from its middle, 0 there to 1 at the edge: a bell, full in the middle
// and nothing at the edge, fading faster the higher the falloff
function engineGlowAlpha(r, falloff)
{
    const k = 3.5 * falloff, edge = Math.exp(-k);
    return (Math.exp(-k * r * r) - edge) / (1 - edge);
}

// the soft round glow of the 2D and 3D lights, one texture for each falloff, rounded to a tenth so a changing falloff
// makes only a few, each made once from a canvas; undefined headless or without a canvas
const engineGlowTextures = new Map;
function engineGlowTexture(falloff=1)
{
    ASSERT(isNumber(falloff) && falloff > 0, 'glowFalloff must be a number above 0');
    const key = max(round(falloff * 10), 1) / 10;
    let texture = engineGlowTextures.get(key);
    if (texture || !glContext || typeof OffscreenCanvas == 'undefined') return texture;
    const size = 64, context = createCanvasContext(size), steps = 16;
    const gradient = context.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2);
    for (let i = 0; i <= steps; ++i)
        gradient.addColorStop(i / steps, 'rgba(255,255,255,' + engineGlowAlpha(i / steps, key).toFixed(4) + ')');
    context.fillStyle = gradient;
    context.fillRect(0, 0, size, size);
    engineGlowTextures.set(key, texture = new TextureInfo(context.canvas, true, false, false));
    return texture;
}

// load engine font, called automatically on startup
async function imageFontInit()
{
    const image = new Image;
    await new Promise(resolve =>
    {
        image.onerror = image.onload = resolve;
        image.crossOrigin = 'anonymous';
        image.src = 'data:image/png;base64,';
    });
    
    const tilePos=vec2(), tileSize=vec2(8), padding=1, bleed=0;
    const textureInfo = new TextureInfo(image);
    const tileInfo = new TileInfo(tilePos, tileSize, textureInfo, padding, bleed);
    engineImageFont = new ImageFont(tileInfo);
}
/**
 * LittleJS Input System
 * - Keyboard input with key down, pressed, and released states
 * - Mouse input with position (world and screen space), buttons, and wheel
 * - Gamepad support for multiple controllers with analog sticks and buttons
 * - Touch input mapped to mouse position and buttons
 * - Virtual on-screen gamepad for mobile devices
 * - Automatic gamepad vs keyboard/mouse detection
 * - Input event prevention for canvas focus
 * - Clipboard copy/paste support
 * @namespace Input
 */

/** Mouse pos in world space
 *  @type {Vector2}
 *  @memberof Input */
let mousePos = vec2();

/** Mouse pos in screen space
 *  @type {Vector2}
 *  @memberof Input */
let mousePosScreen = vec2();

/** Mouse movement delta in world space
 *  @type {Vector2}
 *  @memberof Input */
let mouseDelta = vec2();

/** Mouse movement delta in screen space
 *  @type {Vector2}
 *  @memberof Input */
let mouseDeltaScreen = vec2();

/** Mouse wheel delta this frame
 *  @type {number}
 *  @memberof Input */
let mouseWheel = 0;

/** Touch pinch delta this frame, in the mouse wheel's units: two fingers moving apart are negative, as the wheel
 *  turned up is, and moving together positive, 1 for every 50 pixels; added to mouseWheel while touchPinchWheel
 *  is on, so a game that zooms with the wheel zooms with a pinch
 *  @type {number}
 *  @memberof Input */
let touchPinch = 0;

/** True if mouse was inside the document window, set to false when mouse leaves
 *  @type {boolean}
 *  @memberof Input */
let mouseInWindow = true;

/** True if a gamepad is the most recently used input device.
 *  Equivalent to usingGamepadInput(); derived from lastInputDevice each frame.
 *  @type {boolean}
 *  @memberof Input */
let isUsingGamepad = false;

/** The most recently used input device: 'mouse' | 'keyboard' | 'gamepad'.
 *  Sticky: it holds its value while every device is idle, so a mouse-follow
 *  control (e.g. paddle = mousePos) won't snap back the instant the stick/keys
 *  are released. With several devices in play at once (e.g. keyboard to move +
 *  mouse to aim) it tracks whichever was touched last each frame, so it may
 *  alternate — that's intended; use it to pick which control drives a shared
 *  action. Updated every frame by inputUpdate().
 *  @type {'mouse'|'keyboard'|'gamepad'}
 *  @memberof Input */
let lastInputDevice = 'mouse';

/** Screen-pixel mouse movement per frame that counts as "using the mouse"
 *  (so sub-pixel hand jitter doesn't steal focus from the keyboard/gamepad).
 *  @type {number}
 *  @default
 *  @memberof Input */
let inputMouseMoveThreshold = 6;

/** Prevents input continuing to the default browser handling (true by default)
 *  @type {boolean}
 *  @memberof Input */
let inputPreventDefault = true;

/** Primary gamepad index, automatically set to first gamepad with input
 *  @type {number}
 *  @memberof Input */
let gamepadPrimary = 0;

/** True if a touch device has been detected
 *  @memberof Input */
const isTouchDevice = !headlessMode && typeof window != 'undefined' && window.ontouchstart !== undefined;

/** Prevents input continuing to the default browser handling
 *  This is useful to disable for html menus so the browser can handle input normally,
 *  the right click menu included; over an html text field that menu always shows
 *  - While on, the mouse's back and forward buttons don't leave the page, a game can read them as mouse 3 and 4
 *  @param {boolean} [preventDefault]
 *  @memberof Input */
function setInputPreventDefault(preventDefault=true) { inputPreventDefault = preventDefault; }

/** Set the screen-pixel mouse movement per frame that counts as using the mouse
 *  @param {number} threshold
 *  @memberof Input */
function setInputMouseMoveThreshold(threshold) { inputMouseMoveThreshold = threshold; }

/** Is the mouse the most recently used input device?
 *  @return {boolean}
 *  @memberof Input */
function usingMouseInput() { return lastInputDevice === 'mouse'; }
/** Is the keyboard the most recently used input device?
 *  @return {boolean}
 *  @memberof Input */
function usingKeyboardInput() { return lastInputDevice === 'keyboard'; }
/** Is a gamepad the most recently used input device?
 *  @return {boolean}
 *  @memberof Input */
function usingGamepadInput() { return lastInputDevice === 'gamepad'; }

/** Clear a key's state, so it stops reading as down, pressed or released this frame; a key still held is not
 *  pressed again until it is let go
 *  @param {string|number} key - A key code like 'Space', or a mouse or gamepad button number
 *  @param {number} [device] - 0 for the keyboard and mouse, gamepad n is device n + 1
 *  @param {boolean} [clearDown] - Clear the held state
 *  @param {boolean} [clearPressed] - Clear the pressed this frame state
 *  @param {boolean} [clearReleased] - Clear the released this frame state
 *  @memberof Input */
function inputClearKey(key, device=0, clearDown=true, clearPressed=true, clearReleased=true)
{
    if (!inputData[device])
        return;
    inputData[device][key] &= ~((clearDown?1:0)|(clearPressed?2:0)|(clearReleased?4:0));
}

// the WASD keys and the arrows they stand in for when inputWASDEmulateDirection is on, and the arrows' aliases
const inputWASDToArrow = {KeyW:'ArrowUp', KeyS:'ArrowDown', KeyA:'ArrowLeft', KeyD:'ArrowRight'};
const inputArrowToWASD = {ArrowUp:'KeyW', ArrowDown:'KeyS', ArrowLeft:'KeyA', ArrowRight:'KeyD'};
const inputKeysHeld = new Set; // the keys physically down, since an arrow's slot is shared with its alias
let inputPinch; // the two fingers pinching and how far apart they were, undefined with no pinch
let inputWasTouching = 0, inputTouchIdentifier; // the touch driving the mouse, cleared with the input so only a new touch presses
let inputLastTouchTime = -1e9; // when a touch event last came, the mouse events a browser makes from a tap follow it

